import{_ as a,b as s,f as e,I as p}from"./chunks/framework.DYvp_Vyw.js";const d=JSON.parse('{"title":"Java期末复习笔记 - 第四章 - 流程控制","description":"","frontmatter":{"title":"Java期末复习笔记 - 第四章 - 流程控制","date":"2025-05-07T01:51:13.000Z","tags":["Java"],"head":[["meta",{"name":"descriptionx x x","content":"vitepress-theme-bluearchive Tags"}],["meta",{"name":"keywords","content":"vitepress theme bluearchive Tags"}]]},"headers":[],"relativePath":"posts/Java-Own-Study-004.md","filePath":"posts/Java-Own-Study-004.md"}'),l={name:"posts/Java-Own-Study-004.md"};function i(t,n,r,c,o,u){return e(),s("div",null,n[0]||(n[0]=[p(`<p>大二上学期的期末复习笔记。</p><hr><div style="text-align:center;"><h1>流程控制</h1></div><h1 id="_1-语句与复合语句" tabindex="-1"><u style="text-decoration:underline;text-decoration-color:deepskyblue;">1.语句与复合语句 </u> <a class="header-anchor" href="#_1-语句与复合语句" aria-label="Permalink to &quot;&lt;u style=&quot;text-decoration: underline; text-decoration-color: deepskyblue;&quot;&gt;1.语句与复合语句 &lt;/u&gt;&quot;">​</a></h1><h3 id="_1-1-定义" tabindex="-1">1.1 定义 <a class="header-anchor" href="#_1-1-定义" aria-label="Permalink to &quot;1.1 定义&quot;">​</a></h3><p>语句可以是以分号“；”结尾的简单语句，也可以是用一对花括号“{}”括起来的复合语句。</p><blockquote><p>一个复合语句可以嵌套另一个复合语句。Java语言不允许在两个嵌套的复合语句内声明同名变量。</p></blockquote><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span>public class NestedBlocks {</span></span>
<span class="line"><span>    public static void main(String[] args) {</span></span>
<span class="line"><span>        // 外层复合语句</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            int x = 10; // 在外层复合语句中声明变量 x</span></span>
<span class="line"><span>            System.out.println(&quot;外层 x: &quot; + x);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>            // 内层复合语句</span></span>
<span class="line"><span>            {</span></span>
<span class="line"><span>                int y = 20; // 在内层复合语句中声明变量 y</span></span>
<span class="line"><span>                System.out.println(&quot;内层 y: &quot; + y);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>                // 下面的代码会导致编译错误，因为 x 已经在外层声明</span></span>
<span class="line"><span>                // int x = 30;</span><span> // Uncommenting this line will cause a compilation error</span></span>
<span class="line"><span></span></span>
<span class="line"><span>                // 你可以在内层使用外层的 x</span></span>
<span class="line"><span>                System.out.println(&quot;内层访问外层 x: &quot; + x);</span></span>
<span class="line"><span>            }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>            // 仍然可以访问外层的 x</span></span>
<span class="line"><span>            System.out.println(&quot;再次访问外层 x: &quot; + x);</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        // 这里，x 是不可见的，因为它只在外层复合语句的作用域内</span></span>
<span class="line"><span>        // System.out.println(x);</span><span> // Uncommenting this line will cause a compilation error</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br></div></div><h3 id="_1-2-java语言的三种注释形式" tabindex="-1">1.2 Java语言的三种注释形式 <a class="header-anchor" href="#_1-2-java语言的三种注释形式" aria-label="Permalink to &quot;1.2 Java语言的三种注释形式&quot;">​</a></h3><p>1.单行注释。单行注释以“ // ”开头，至该行行尾。其格式如下：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span>//单行注释（comment on one line）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>2.多行注释。多行注释也称为段注释或块注释，以“ /* ”开头，以“ */ ”结束。其格式如下：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span>/*单行或多行注释</span></span>
<span class="line"><span>（comment on one or more lines）*/</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>3.文件注释。文件注释是Java语言所特有的文档注释。它以“ <code>/**</code> ”开头，以“ */ ”结尾。这种注释主要用于描述类、数据和方法。它是使用JDK提供的javadoc.exe命令所生成的扩展名为.html的文件，从而为程序提供文档说明。</p><blockquote><p>中间的if while等将以视频的形式讲解（过于基础，文档中暂时不涉及）</p></blockquote><h1 id="本章小结" tabindex="-1"><u style="text-decoration:underline;text-decoration-color:deepskyblue;">本章小结</u> <a class="header-anchor" href="#本章小结" aria-label="Permalink to &quot;&lt;u style=&quot;text-decoration: underline; text-decoration-color: deepskyblue;&quot;&gt;本章小结&lt;/u&gt;&quot;">​</a></h1><p>1.Java语言的流程控制方式是结构化程序设计中规定的三种基本流程结构：顺序结构，分支结构（或称选择结构）和循环结构。</p><p>2.选择结构包括if、if-else和switch三种语句。在程序中使用选择结构，就像处在十字路口一样，根据不同的选择，程序的运行会有不同的方向与结果。</p><p>3.Java语言提供了三种循环控制语句：for、while和do-while。</p><p>4.在循环里也可以声明变量，但所声明的变量，是局部变量，只要退出循环，这个变量就不存在了。</p><p>5.递归是程序控制的另一个形式，其本质就是不用循环去控制某段代码的重复执行。</p><blockquote><p>尽管递归有许多优点，但也要注意其潜在缺点，如栈溢出和性能问题。</p></blockquote><h2 id="_6-递归方法就是直接或间接调用方法自身。要终止一个递归方法-必须有一个或多个终止条件。" tabindex="-1">6.递归方法就是直接或间接调用方法自身。要终止一个递归方法，必须有一个或多个终止条件。 <a class="header-anchor" href="#_6-递归方法就是直接或间接调用方法自身。要终止一个递归方法-必须有一个或多个终止条件。" aria-label="Permalink to &quot;6.递归方法就是直接或间接调用方法自身。要终止一个递归方法，必须有一个或多个终止条件。&quot;">​</a></h2>`,23)]))}const m=a(l,[["render",i]]);export{d as __pageData,m as default};
